"""Core DAG runner for the mini data harness."""

from __future__ import annotations

import csv
import json
import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable, Iterable

MAX_STAGE_RETRIES = 2


@dataclass(frozen=True)
class HarnessResult:
    records: list[dict[str, Any]]
    rejects: list[dict[str, Any]]
    report: dict[str, Any]
    logs: list[dict[str, Any]]


def repo_root() -> Path:
    return Path(__file__).resolve().parents[2]


def resolve_from_root(path: str | Path, root: Path | None = None) -> Path:
    candidate = Path(path)
    if candidate.is_absolute():
        return candidate
    return (root or repo_root()) / candidate


def snake_case(value: str) -> str:
    value = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", value.strip())
    value = re.sub(r"[^0-9A-Za-z]+", "_", value)
    return value.strip("_").lower()


def extract_records(paths: Iterable[str | Path], root: Path | None = None) -> list[dict[str, Any]]:
    extracted: list[dict[str, Any]] = []
    base = root or repo_root()
    for raw_path in paths:
        path = resolve_from_root(raw_path, base)
        suffix = path.suffix.lower()
        if suffix == ".csv":
            extracted.extend(_read_csv(path, base))
        elif suffix == ".jsonl":
            extracted.extend(_read_jsonl(path, base))
        else:
            raise ValueError(f"unsupported input type: {path}")
    return extracted


def clean_records(records: Iterable[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    cleaned: list[dict[str, Any]] = []
    rejects: list[dict[str, Any]] = []

    for index, record in enumerate(records, start=1):
        normalized = {
            snake_case(str(key)): value.strip() if isinstance(value, str) else value
            for key, value in record.items()
        }
        if _is_empty_record(_record_without_metadata(normalized)):
            continue
        if not str(normalized.get("id", "")).strip():
            rejects.append(
                {
                    "reason": "missing_id",
                    "record_index": index,
                    "record": normalized,
                    "source_file": normalized.get("source_file") or record.get("_source_file"),
                }
            )
            continue
        cleaned.append(normalized)
    return cleaned, rejects


def build_report(
    records: list[dict[str, Any]],
    rejects: list[dict[str, Any]],
    retry_count: int,
    source_files: Iterable[str],
) -> dict[str, Any]:
    return {
        "processed_count": len(records),
        "rejected_count": len(rejects),
        "retry_count": retry_count,
        "source_files": list(source_files),
    }


def run_dag(
    input_paths: Iterable[str | Path],
    *,
    max_retries: int = 2,
    root: Path | None = None,
) -> HarnessResult:
    base = root or repo_root()
    resolved_inputs = [resolve_from_root(path, base) for path in input_paths]
    retry_limit = max(0, min(max_retries, MAX_STAGE_RETRIES))
    logs: list[dict[str, Any]] = []
    retry_count = 0

    extracted, retries = _run_stage(
        "extract",
        lambda: extract_records(resolved_inputs, base),
        logs,
        retry_limit,
    )
    retry_count += retries

    cleaned_result, retries = _run_stage(
        "clean",
        lambda: clean_records(extracted),
        logs,
        retry_limit,
    )
    retry_count += retries
    records, rejects = cleaned_result

    source_files = [_relative_or_absolute(path, base) for path in resolved_inputs]
    report, retries = _run_stage(
        "report",
        lambda: build_report(records, rejects, retry_count, source_files),
        logs,
        retry_limit,
    )
    retry_count += retries
    report["retry_count"] = retry_count

    return HarnessResult(records=records, rejects=rejects, report=report, logs=logs)


def write_jsonl(path: str | Path, rows: Iterable[dict[str, Any]]) -> None:
    target = Path(path)
    with target.open("w", encoding="utf-8", newline="\n") as handle:
        for row in rows:
            handle.write(json.dumps(row, sort_keys=True) + "\n")


def _run_stage(
    stage: str,
    func: Callable[[], Any],
    logs: list[dict[str, Any]],
    max_retries: int,
) -> tuple[Any, int]:
    retry_limit = max(0, min(max_retries, MAX_STAGE_RETRIES))
    retry_count = 0
    for attempt in range(1, retry_limit + 2):
        try:
            result = func()
        except Exception as exc:
            status = "retrying" if attempt <= retry_limit else "failed"
            logs.append(
                {
                    "attempt": attempt,
                    "stage": stage,
                    "status": status,
                    "error": str(exc),
                }
            )
            if attempt > retry_limit:
                raise
            retry_count += 1
        else:
            logs.append({"attempt": attempt, "stage": stage, "status": "ok"})
            return result, retry_count
    raise RuntimeError(f"stage did not complete: {stage}")


def _read_csv(path: Path, root: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    with path.open("r", encoding="utf-8", newline="") as handle:
        filtered_lines = [
            line
            for line in handle
            if line.strip() and not line.lstrip().startswith("#")
        ]
    if not filtered_lines:
        return rows
    reader = csv.DictReader(filtered_lines)
    for row in reader:
        if _is_empty_record(row):
            continue
        row["_source_file"] = _relative_or_absolute(path, root)
        rows.append(row)
    return rows


def _read_jsonl(path: Path, root: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    with path.open("r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, start=1):
            if not line.strip():
                continue
            value = json.loads(line)
            if not isinstance(value, dict):
                raise ValueError(f"{path}:{line_number} is not a JSON object")
            value["_source_file"] = _relative_or_absolute(path, root)
            rows.append(value)
    return rows


def _is_empty_record(record: dict[str, Any]) -> bool:
    return all(not str(value).strip() for value in record.values())


def _record_without_metadata(record: dict[str, Any]) -> dict[str, Any]:
    return {
        key: value
        for key, value in record.items()
        if key not in {"_source_file", "source_file"}
    }


def _relative_or_absolute(path: Path, root: Path) -> str:
    try:
        return path.resolve().relative_to(root.resolve()).as_posix()
    except ValueError:
        return str(path)

"""Configuration loading for mini_harness."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .runner import repo_root, resolve_from_root


DEFAULT_INPUTS = ["data/input.csv", "data/events.jsonl"]
DEFAULT_OUTPUT = "evidence/report.json"
DEFAULT_REJECTS_OUTPUT = "evidence/rejects.jsonl"
DEFAULT_LOG_OUTPUT = "logs/mini_harness.jsonl"
DEFAULT_MAX_RETRIES = 2
DEFAULT_CONFIG_NAMES = ("harness.json", "harness.yaml", "harness.yml")


@dataclass(frozen=True)
class HarnessConfig:
    inputs: list[str]
    output: str
    rejects_output: str
    log_output: str
    max_retries: int


def default_config() -> HarnessConfig:
    return HarnessConfig(
        inputs=list(DEFAULT_INPUTS),
        output=DEFAULT_OUTPUT,
        rejects_output=DEFAULT_REJECTS_OUTPUT,
        log_output=DEFAULT_LOG_OUTPUT,
        max_retries=DEFAULT_MAX_RETRIES,
    )


def load_config(path: str | Path | None = None, root: Path | None = None) -> HarnessConfig:
    base = root or repo_root()
    config_path = _find_config(path, base)
    if config_path is None:
        return default_config()

    raw = _load_mapping(config_path)
    defaults = default_config()
    return HarnessConfig(
        inputs=_string_list(raw.get("inputs", defaults.inputs), "inputs"),
        output=str(raw.get("output", defaults.output)),
        rejects_output=str(raw.get("rejects_output", defaults.rejects_output)),
        log_output=str(raw.get("log_output", defaults.log_output)),
        max_retries=int(raw.get("max_retries", defaults.max_retries)),
    )


def merge_config(
    config: HarnessConfig,
    *,
    inputs: list[str] | None = None,
    output: str | None = None,
    rejects_output: str | None = None,
    log_output: str | None = None,
    max_retries: int | None = None,
) -> HarnessConfig:
    return HarnessConfig(
        inputs=inputs if inputs is not None else config.inputs,
        output=output if output is not None else config.output,
        rejects_output=rejects_output if rejects_output is not None else config.rejects_output,
        log_output=log_output if log_output is not None else config.log_output,
        max_retries=max_retries if max_retries is not None else config.max_retries,
    )


def _find_config(path: str | Path | None, root: Path) -> Path | None:
    if path is not None:
        config_path = resolve_from_root(path, root)
        if not config_path.exists():
            raise FileNotFoundError(f"config file not found: {config_path}")
        return config_path

    for name in DEFAULT_CONFIG_NAMES:
        candidate = root / name
        if candidate.exists():
            return candidate
    return None


def _load_mapping(path: Path) -> dict[str, Any]:
    suffix = path.suffix.lower()
    if suffix == ".json":
        value = json.loads(path.read_text(encoding="utf-8"))
    elif suffix in {".yaml", ".yml"}:
        value = _parse_simple_yaml(path.read_text(encoding="utf-8"))
    else:
        raise ValueError(f"unsupported config type: {path}")
    if not isinstance(value, dict):
        raise ValueError(f"config must be a mapping: {path}")
    return value


def _parse_simple_yaml(text: str) -> dict[str, Any]:
    data: dict[str, Any] = {}
    current_list_key: str | None = None

    for line_number, raw_line in enumerate(text.splitlines(), start=1):
        stripped = raw_line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith("- "):
            if current_list_key is None:
                raise ValueError(f"YAML list item without key on line {line_number}")
            data[current_list_key].append(_parse_scalar(stripped[2:].strip()))
            continue
        if ":" not in stripped:
            raise ValueError(f"unsupported YAML syntax on line {line_number}")

        key, raw_value = stripped.split(":", 1)
        key = key.strip()
        raw_value = raw_value.strip()
        if not key:
            raise ValueError(f"empty YAML key on line {line_number}")
        if raw_value:
            data[key] = _parse_scalar(raw_value)
            current_list_key = None
        else:
            data[key] = []
            current_list_key = key
    return data


def _parse_scalar(value: str) -> Any:
    value = _strip_quotes(value)
    if value.lower() in {"true", "false"}:
        return value.lower() == "true"
    try:
        return int(value)
    except ValueError:
        return value


def _strip_quotes(value: str) -> str:
    if len(value) >= 2 and value[0] == value[-1] and value[0] in {'"', "'"}:
        return value[1:-1]
    return value


def _string_list(value: Any, field_name: str) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        return [str(item) for item in value]
    raise ValueError(f"{field_name} must be a string or list of strings")

